-- ==============================================================================
-- SynChat: Benchmark Cleanup Script
-- Safely cleans up ONLY benchmark records generated by benchmark_seed_200_conversations.sql
-- ==============================================================================

DO $$
BEGIN
    IF current_database() NOT IN ('synchat', 'synchat_test', 'synchat_dev') THEN
        RAISE EXCEPTION 'SAFETY CHECK FAILED: Refusing to run on database "%". Only synchat, synchat_test, synchat_dev are allowed.', current_database();
    END IF;
END $$;

BEGIN;

DO $$
DECLARE
    deleted_messages INT;
    deleted_members INT;
    deleted_conversations INT;
    deleted_sessions INT;
    deleted_devices INT;
    deleted_credentials INT;
    deleted_offsets INT;
    deleted_users INT;
BEGIN
    -- 1. Delete messages (foreign key sender_id has NO cascade)
    WITH benchmark_conv_ids AS (
        SELECT id FROM conversations
        WHERE direct_key LIKE 'direct:a0000000-0000-0000-0000-000000000001:%'
          AND id >= 'c0000000-0000-0000-0000-000000000001'::uuid
          AND id <= 'c0000000-0000-0000-0000-000000000200'::uuid
    ),
    del_msg AS (
        DELETE FROM messages
        WHERE conversation_id IN (SELECT id FROM benchmark_conv_ids)
           OR body LIKE '[BENCHMARK]%'
        RETURNING id
    )
    SELECT count(*) INTO deleted_messages FROM del_msg;

    -- 2. Delete conversation members
    WITH benchmark_conv_ids AS (
        SELECT id FROM conversations
        WHERE direct_key LIKE 'direct:a0000000-0000-0000-0000-000000000001:%'
          AND id >= 'c0000000-0000-0000-0000-000000000001'::uuid
          AND id <= 'c0000000-0000-0000-0000-000000000200'::uuid
    ),
    del_mem AS (
        DELETE FROM conversation_members
        WHERE conversation_id IN (SELECT id FROM benchmark_conv_ids)
        RETURNING conversation_id
    )
    SELECT count(*) INTO deleted_members FROM del_mem;

    -- 3. Delete conversations
    WITH del_conv AS (
        DELETE FROM conversations
        WHERE direct_key LIKE 'direct:a0000000-0000-0000-0000-000000000001:%'
          AND id >= 'c0000000-0000-0000-0000-000000000001'::uuid
          AND id <= 'c0000000-0000-0000-0000-000000000200'::uuid
        RETURNING id
    )
    SELECT count(*) INTO deleted_conversations FROM del_conv;

    -- 4. Delete auth sessions and devices if User A logged in during benchmark
    WITH del_sess AS (
        DELETE FROM auth_sessions
        WHERE user_id = 'a0000000-0000-0000-0000-000000000001'::uuid
        RETURNING id
    )
    SELECT count(*) INTO deleted_sessions FROM del_sess;

    WITH del_dev AS (
        DELETE FROM devices
        WHERE user_id = 'a0000000-0000-0000-0000-000000000001'::uuid
        RETURNING id
    )
    SELECT count(*) INTO deleted_devices FROM del_dev;

    -- 5. Delete user credentials & offsets
    WITH del_cred AS (
        DELETE FROM user_credentials
        WHERE user_id = 'a0000000-0000-0000-0000-000000000001'::uuid
        RETURNING user_id
    )
    SELECT count(*) INTO deleted_credentials FROM del_cred;

    WITH del_off AS (
        DELETE FROM user_event_offsets
        WHERE user_id = 'a0000000-0000-0000-0000-000000000001'::uuid
        RETURNING user_id
    )
    SELECT count(*) INTO deleted_offsets FROM del_off;

    -- 6. Delete users (User A + 200 Peers)
    WITH del_usr AS (
        DELETE FROM users
        WHERE id = 'a0000000-0000-0000-0000-000000000001'::uuid
           OR (
               email LIKE 'benchmark.peer.%@synchat.test'
               AND id >= 'b0000000-0000-0000-0000-000000000001'::uuid
               AND id <= 'b0000000-0000-0000-0000-000000000200'::uuid
           )
        RETURNING id
    )
    SELECT count(*) INTO deleted_users FROM del_usr;

    RAISE NOTICE '--- BENCHMARK CLEANUP SUMMARY ---';
    RAISE NOTICE 'Deleted messages:      %', deleted_messages;
    RAISE NOTICE 'Deleted conv members:  %', deleted_members;
    RAISE NOTICE 'Deleted conversations: %', deleted_conversations;
    RAISE NOTICE 'Deleted auth sessions: %', deleted_sessions;
    RAISE NOTICE 'Deleted devices:       %', deleted_devices;
    RAISE NOTICE 'Deleted credentials:   %', deleted_credentials;
    RAISE NOTICE 'Deleted event offsets: %', deleted_offsets;
    RAISE NOTICE 'Deleted users:         %', deleted_users;
END $$;

COMMIT;

-- ==============================================================================
-- End of Cleanup Script
-- ==============================================================================
